#!/usr/bin/env bash
set -euo pipefail

audio_dir="public/media/audio"
image_dir="public/media/infographics"
mkdir -p "$audio_dir" "$image_dir"

download() {
  local url="$1"
  local target="$2"
  if [[ -s "$target" ]]; then
    echo "Déjà présent : $target"
    return
  fi
  curl -L --fail --silent --show-error \
    --referer "https://vulgarimatique.softr.app/" \
    -H "Origin: https://vulgarimatique.softr.app" \
    "$url" -o "$target"
  echo "Téléchargé : $target"
}

